import json, re

clean = re.sub(r'\x1b\[[0-9;]*m', '', comp_output)
if "(.venv)" in clean:
    clean = clean[:clean.index("(.venv)")].strip()

# Parse sections
sections = clean.split("\n=== ")
user_json_str = sections[0].split("=== USER ===\n")[1].strip() if "USER" in sections[0] else ""

# Parse user
user_block = None
cart_block = None
cart_items_list = []
product_map = {}
promos_list = []

for section in clean.split("\n\n"):
    section = section.strip()
    if section.startswith("=== USER ==="):
        json_part = section.replace("=== USER ===", "").strip()
        user_block = json.loads(json_part)
    elif section.startswith("=== CART ==="):
        json_part = section.replace("=== CART ===", "").strip()
        cart_block = json.loads(json_part)
    elif section.startswith("=== CART ITEMS ==="):
        lines = section.replace("=== CART ITEMS ===", "").strip().split("\n")
        for line in lines:
            line = line.strip()
            if line.startswith("{"):
                cart_items_list.append(json.loads(line))
    elif section.startswith("=== ALL PROMOTIONS ==="):
        lines = section.replace("=== ALL PROMOTIONS ===", "").strip().split("\n")
        for line in lines:
            line = line.strip()
            if line.startswith("{"):
                promos_list.append(json.loads(line))

# Parse products from PRODUCT: lines
for line in clean.split("\n"):
    line = line.strip()
    if line.startswith("PRODUCT:"):
        product_map[json.loads(line[8:].strip())['product_id']] = json.loads(line[8:].strip())

print("User:", json.dumps(user_block, indent=2))
print("\nCart:", json.dumps(cart_block, indent=2))
print("\nCart Items:", cart_items_list)
print("\nProducts:", product_map)
print("\nPromos:", len(promos_list))
for p in promos_list:
    print(f"  {p['promo_code']}: {p['description']} | {p['discount_type']} {p['discount_value']}% | min=${p['min_purchase']} | max_discount=${p['max_discount']} | expires={p['expiry_date']} | active={p['active']}")
